package com.game_manager.gm.machine;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;import com.game_manager.gm.gamingsession.*;import com.game_manager.gm.gamingsession.command.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class StationEnforcementProjectionServiceTest {private final StationClientEnforcementRepository states=mock(StationClientEnforcementRepository.class);private final StationReconciliationAuditRepository audits=mock(StationReconciliationAuditRepository.class);private final StationEnforcementProjectionService service=new StationEnforcementProjectionService(states,audits,Clock.fixed(Instant.parse("2026-08-16T12:00:00Z"),ZoneOffset.UTC));
 @Test void terminatedSessionRemainsUnavailableUntilMatchingLockAck(){UUID station=UUID.randomUUID(),sessionId=UUID.randomUUID(),identity=UUID.randomUUID();StationClientEnforcement state=new StationClientEnforcement();state.setStationId(station);state.setEnforcementStatus(StationEnforcementStatus.UNLOCKED);state.setLastCommandSequence(4L);when(states.findById(station)).thenReturn(Optional.of(state));GamingSession session=new GamingSession();session.setId(sessionId);session.setResourceId(station);service.commandIssued(session,StationCommandType.SESSION_TERMINATED,5);assertThat(state.getEnforcementStatus()).isEqualTo(StationEnforcementStatus.LOCK_PENDING);assertThat(service.safeForNewSession(station)).isFalse();service.lockAck(new MachinePrincipal(identity,station,1),sessionId,5,null,"locally locked");assertThat(state.getEnforcementStatus()).isEqualTo(StationEnforcementStatus.LOCKED);assertThat(service.safeForNewSession(station)).isTrue();verify(audits,times(2)).save(any());}
 @Test void duplicateLockAckDoesNotMoveCursorBackwards(){UUID station=UUID.randomUUID(),session=UUID.randomUUID();StationClientEnforcement state=new StationClientEnforcement();state.setStationId(station);state.setSessionId(session);state.setLastCommandSequence(9L);state.setEnforcementStatus(StationEnforcementStatus.LOCKED);when(states.findById(station)).thenReturn(Optional.of(state));service.lockAck(new MachinePrincipal(UUID.randomUUID(),station,1),session,8,null,"duplicate");assertThat(state.getLastCommandSequence()).isEqualTo(9L);assertThat(state.getEnforcementStatus()).isEqualTo(StationEnforcementStatus.LOCKED);}
}
